def build_kdtree(points, depth=0, k={{k_dim}}):
    if not points: return None
    axis = depth % k
    points.sort(key=lambda p: p[axis])
    mid = len(points)//2
    return {'p': points[mid], 'axis': axis,
            'l': build_kdtree(points[:mid], depth+1, k),
            'r': build_kdtree(points[mid+1:], depth+1, k)}

def nn(node, q={{query}}, best=None):
    if node is None: return best
    d = sum((a-b)**2 for a, b in zip(node['p'], q))
    if best is None or d < best[0]: best = (d, node['p'])
    diff = q[node['axis']] - node['p'][node['axis']]
    first, second = (node['l'], node['r']) if diff < 0 else (node['r'], node['l'])
    best = nn(first, q, best)
    if diff*diff < best[0]: best = nn(second, q, best)
    return best
